"""Evaluate research claims against a supplied evidence set and policy."""

import copy
import json


def _canonical(value):
    """Return a stable JSON representation for value comparison."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def evaluate(request, evidence, policy):
    """Evaluate one request using only the supplied evidence and policy."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and not record.get("verified", False):
            continue

        conditions = record.get("conditions", {})
        if any(
            name not in conditions
            or _canonical(conditions[name]) != _canonical(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = set()
    for record in eligible:
        replaced = record.get("supersedes", [])
        if isinstance(replaced, str):
            replaced = [replaced]
        elif isinstance(replaced, list):
            replaced = [item for item in replaced if isinstance(item, str)]
        else:
            replaced = []
        superseded.update(
            item for item in replaced if item != record.get("source")
        )

    eligible = [
        record for record in eligible if record.get("source") not in superseded
    ]
    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted({record["source"] for record in eligible})
    values = {}
    for record in eligible:
        key = _canonical(record.get("value"))
        values.setdefault(key, record.get("value"))

    if len(values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = next(iter(values.values()))
    return {
        "status": "unsupported" if value is False else "supported",
        "value": copy.deepcopy(value),
        "sources": sources,
        "unknowns": [],
    }

